'use client';

import { type RefObject, useEffect } from 'react';

import {
    applySidebarProximityFromPointer,
    clearSidebarProximityStyles,
    prefersReducedMotion,
} from '@/components/Sidebar/sidebar-proximity';

/**
 * Cursor-proximity highlight for sidebar nav rows.
 * Disabled when `prefers-reduced-motion: reduce`.
 */
export function useSidebarProximity(containerRef: RefObject<HTMLElement | null>) {
    useEffect(() => {
        const root = containerRef.current;
        if (!root) return;

        let rafId = 0;
        let lastY = 0;
        let attached = false;

        const media =
            typeof window.matchMedia === 'function'
                ? window.matchMedia('(prefers-reduced-motion: reduce)')
                : null;

        function detach() {
            if (!attached) return;
            attached = false;
            root!.removeEventListener('pointermove', onPointerMove);
            root!.removeEventListener('pointerleave', onPointerLeave);
            if (rafId) {
                cancelAnimationFrame(rafId);
                rafId = 0;
            }
            clearSidebarProximityStyles(root!);
        }

        function flush() {
            rafId = 0;
            if (prefersReducedMotion()) {
                clearSidebarProximityStyles(root!);
                return;
            }
            applySidebarProximityFromPointer(root!, lastY);
        }

        function onPointerMove(event: PointerEvent) {
            lastY = event.clientY;
            if (rafId) return;
            rafId = requestAnimationFrame(flush);
        }

        function onPointerLeave() {
            if (rafId) {
                cancelAnimationFrame(rafId);
                rafId = 0;
            }

