function prefersReducedMotion(): boolean {
    if (typeof window === 'undefined') return false;
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

function queryRing(): HTMLElement | null {
    if (typeof document === 'undefined') return null;
    return document.querySelector<HTMLElement>('[data-broker-activation-highlight]');
}

function resolveRingRadius(target: Element): string {
    if (typeof window === 'undefined') return `${RING_RADIUS_FALLBACK_PX}px`;
    const raw = window.getComputedStyle(target).borderRadius?.trim();
    if (raw && raw !== '0px') return raw;
    return `${RING_RADIUS_FALLBACK_PX}px`;
}

